R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-2';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(37,'tomorrow-soaking-overnight','Tomorrow soaking overnight','The restless night finally finds order in ordinary kitchen preparations: soaking pulses and setting curd. One bowl of chickpeas holds this quiet preparation for dawn without staging despair or literalizing every image.','Horizontal3:2 intimate transparent watercolor with selective graphite. Close low oblique view of one shallow ordinary stainless-steel bowl half filled with clear water and pale soaked chickpeas on a plain kitchen ledge. Chickpeas irregularly clustered underwater with a few gently breaking surface, believable waterline and muted metal reflections. Bowl toward lower left; quiet cool grey wall and unused ledge to right. A modest warm kitchen light from upper left, soft real shadow beneath bowl, no glow effect. It is late at night but visibly gentle, not pitch black. No decorative ingredients, jars, labels, people, hands, flowers or text. Not a polished recipe photograph.','watercolor and graphite'),(39,'where-the-river-turns','Where the river turns','The speaker welcomes the sudden bend here and now instead of a calculated future. A river turning out of sight preserves that open possibility; no arrows, destination, symbolic clock or invented autobiographical setting.','Horizontal3:2 broad dry pastel and thin gouache landscape. Low bank-level view beside a modest river bending left behind a rounded grassy bank, the far reach gently disappearing from sight. Foreground water occupies lower right; uneven soft grass on left, a few broad leaves partly cropped at top left, modest pale open sky and distant low riverbank. Ordinary overcast daylight, muted blue-green water reflecting sky in broken horizontal strokes, no mist filter, sunset, mountains, temple, boat or people. Let one nearby leaf have a warm brown edge while the rest remain green; very little botanical detail. Unspectacular but alive, asymmetrical and open.','dry pastel and gouache'),(55,'the-painting-left-open','The painting left open','The poem discovers completion within an unfinished image: a distracted brush changes a tree and the river. An unfinished painted sheet makes that process visible without turning incompleteness into a polished allegorical castle.','Horizontal3:2 opaque gouache with sparse pencil; a painted still life seen from a modest high oblique angle. A single unframed cream sheet on an ordinary pale worktable contains a visibly unfinished loose painting: one irregular green tree mass on a bank at left and blue-white river strokes below, broad unpainted paper to right. Several purposeful incomplete edges and a single darker interrupted branch stroke, no carefully balanced botanical diagram. One ordinary paintbrush rests beside the sheet at lower left, handle contacting table, bristles pointing away from paper. No palette rainbow, tubes, flowers, other props, signatures or readable text. Soft neutral daylight. Table and paper perspective coherent. Keep depicted painting fragmentary with differences of brush pressure; do not overfinish it.','gouache and pencil')]
items=[]
for pid,ident,title,reason,scene,medium in rows:
 p=S/f'content/editions/issue-02/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/p.name;snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal3:2 literary artwork for Kabita Live Issue2. Human Natural in Poetic Natural mode. Preserve this expressive medium; an interpretation, not documentary evidence.\nEmotional anchor: {reason}\nScene: {scene}\nAvoid these over-optimized traits: staged symmetry, uniform sharp detail, theatrical lighting, decorative clutter and mechanical surface distress. Use causal material contact, selective marks, ordinary illumination and quiet negative space. No identifiable people, portraits, readable text, signatures, logos or watermarks. Opaque ivory-paper background.\nFull poem context only; never render its words: {d["title"]} by {d["author"]}\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt);items.append(dict(id=ident,edition=2,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-2/{ident}/v1.png',attempts=[],medium_label=medium,independent=False))
